from _codecs import ascii_encode as convert, register_error
class Position:
    def __index__(self):
        pass
        return -1
def handler(error):
    print('cancel')
    return ('!', Position())
register_error('public_core_cancellation', handler)
try:
    convert('\ud800Z', 'public_core_cancellation')
except BaseException:
    print('recovered')

